const payload = $input.first().json.body || $input.first().json;

const startUrl = payload.startUrl || payload.url || 'https://example.com';
let siteHost = '';
try { siteHost = new URL(startUrl).host; } catch (e) { siteHost = ''; }

return [{
  json: {
    startUrl,
    siteHost,
    maxPages: Number(payload.maxPages) || 20,
    maxDepth: Number(payload.maxDepth) || 2,
    queue: [{ url: startUrl, depth: 0 }],
    visited: [],
    pagesCrawled: 0,
    results: []
  }
}];

const item = $input.first().json;
const queue = [...(item.queue || [])];
const next = queue.shift();

return [{
  json: {
    ...item,
    queue,
    currentUrl: next ? next.url : null,
    currentDepth: next ? next.depth : null,
    hasNext: !!next
  }
}];

const state = $('Retrieve URL from Queue').first().json;
const response = $input.first().json;

const html = String(response.data || response.body || '');
const statusCode = response.statusCode || response.status || null;

function extract(re, str) {
  const m = str.match(re);
  return m ? m[1].replace(/\s+/g, ' ').trim() : '';
}

const title = extract(/<title[^>]*>([\s\S]*?)<\/title>/i, html);
const metaDescription = extract(/<meta[^>]+name=["']description["'][^>]+content=["']([^"']*)["']/i, html);
const canonical = extract(/<link[^>]+rel=["']canonical["'][^>]+href=["']([^"']*)["']/i, html);
const metaRobots = extract(/<meta[^>]+name=["']robots["'][^>]+content=["']([^"']*)["']/i, html);

const h1s = [...html.matchAll(/<h1[^>]*>([\s\S]*?)<\/h1>/gi)].map(m => m[1].replace(/<[^>]+>/g, '').trim());
const h2s = [...html.matchAll(/<h2[^>]*>([\s\S]*?)<\/h2>/gi)].map(m => m[1].replace(/<[^>]+>/g, '').trim());

const hasJsonLd = /<script[^>]+type=["']application\/ld\+json["']/i.test(html);

const imgTags = [...html.matchAll(/<img[^>]*>/gi)].map(m => m[0]);
const imagesMissingAlt = imgTags.filter(tag => !/alt=["'][^"']+["']/i.test(tag)).length;

const hrefs = [...html.matchAll(/<a[^>]+href=["']([^"'#]+)["'][^>]*>/gi)].map(m => m[1]);
const internalLinks = [];
const externalLinks = [];
for (const href of hrefs) {
  try {
    const resolved = new URL(href, state.currentUrl).href;
    if (new URL(resolved).host === state.siteHost) internalLinks.push(resolved);
    else externalLinks.push(resolved);
  } catch (e) { /* skip malformed hrefs */ }
}

const textOnly = html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();
const wordCount = textOnly ? textOnly.split(' ').length : 0;

return [{
  json: {
    ...state,
    statusCode,
    title,
    titleLength: title.length,
    metaDescription,
    metaDescriptionLength: metaDescription.length,
    canonical,
    metaRobots,
    h1Count: h1s.length,
    h1s,
    h2s,
    hasJsonLd,
    imagesTotal: imgTags.length,
    imagesMissingAlt,
    internalLinks: [...new Set(internalLinks)],
    externalLinks: [...new Set(externalLinks)],
    internalLinkCount: internalLinks.length,
    externalLinkCount: externalLinks.length,
    wordCount
  }
}];

const item = $input.first().json;
const visited = [...new Set([...(item.visited || []), item.currentUrl])];
let queue = [...(item.queue || [])];

if ((item.currentDepth ?? 0) < item.maxDepth) {
  const queuedUrls = new Set(queue.map(q => q.url));
  for (const link of (item.internalLinks || [])) {
    const clean = link.split('#')[0];
    if (clean && !visited.includes(clean) && !queuedUrls.has(clean)) {
      queue.push({ url: clean, depth: (item.currentDepth ?? 0) + 1 });
      queuedUrls.add(clean);
    }
  }
}

return [{
  json: {
    ...item,
    visited,
    queue,
    pagesCrawled: visited.length
  }
}];

const cfg = $('Update Crawl Queue').first().json;
const items = $input.all().map(i => i.json);

const labels = ['technical', 'intent', 'entity', 'internalLink', 'contentQuality', 'architecture'];

function parseAgent(resp) {
  try {
    const raw = resp.content?.[0]?.text || '{}';
    const cleaned = raw.replace(/```json|```/g, '').trim();
    return JSON.parse(cleaned);
  } catch (e) {
    return { score: null, issues: [], summary: 'Unable to parse agent response' };
  }
}

const agentResults = {};
items.forEach((resp, idx) => {
  agentResults[labels[idx] || ('agent' + idx)] = parseAgent(resp);
});

const scores = Object.values(agentResults).map(a => a.score).filter(s => typeof s === 'number');
const overallScore = scores.length ? Math.round(scores.reduce((a, b) => a + b, 0) / scores.length) : null;

const severityRank = { high: 0, medium: 1, low: 2 };
const allIssues = [];
for (const [agent, result] of Object.entries(agentResults)) {
  for (const issue of (result.issues || [])) {
    allIssues.push({ agent, ...issue });
  }
}
allIssues.sort((a, b) => (severityRank[a.severity] ?? 3) - (severityRank[b.severity] ?? 3));

const pageDiagnosis = {
  url: cfg.currentUrl,
  depth: cfg.currentDepth,
  statusCode: cfg.statusCode,
  overallScore,
  agentScores: Object.fromEntries(Object.entries(agentResults).map(([k, v]) => [k, v.score])),
  issues: allIssues,
  agentSummaries: Object.fromEntries(Object.entries(agentResults).map(([k, v]) => [k, v.summary])),
  crawledAt: new Date().toISOString()
};

return [{
  json: {
    ...cfg,
    results: [...(cfg.results || []), pageDiagnosis]
  }
}];

const item = $input.first().json;
const results = item.results || [];

const totalPages = results.length;
const avgScore = totalPages
  ? Math.round(results.reduce((s, r) => s + (r.overallScore || 0), 0) / totalPages)
  : null;

const issueCounts = {};
for (const r of results) {
  for (const issue of (r.issues || [])) {
    issueCounts[issue.issue] = (issueCounts[issue.issue] || 0) + 1;
  }
}
const topRecurringIssues = Object.entries(issueCounts)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 10)
  .map(([issue, count]) => ({ issue, count }));

const worstPages = [...results]
  .sort((a, b) => (a.overallScore ?? 100) - (b.overallScore ?? 100))
  .slice(0, 5)
  .map(r => ({ url: r.url, overallScore: r.overallScore }));

return [{
  json: {
    siteHost: item.siteHost,
    startUrl: item.startUrl,
    pagesCrawled: totalPages,
    averageScore: avgScore,
    topRecurringIssues,
    worstPages,
    pages: results
  }
}];
